/**
 * @distilled.cloud/clickhouse-cloud -- ClickHouse Cloud API SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` converts from the OpenAPI document ClickHouse
 * Cloud serves at `https://api.clickhouse.cloud/v1`, mirrored at
 * `specs/spec-mirror-clickhouse-cloud/specs/openapi.json`. Everything else in
 * this folder is hand-written.
 *
 * One module per API tag (`service`, `apiKeys`, `clickPipes`, `postgres`,
 * ...), the split the API reference uses. Operations return the `result` of
 * the API's `{ status, requestId, result }` envelope; a cursor page keeps the
 * envelope, with its `result` page beside `nextCursor`.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as ClickHouseCloud from "@distilled.cloud/clickhouse-cloud";
 *
 * const program = Effect.gen(function* () {
 *   const organizations = yield* ClickHouseCloud.organization.listOrganizations({});
 *   const organizationId = organizations.result[0]?.id;
 *   if (organizationId === undefined) return [];
 *
 *   const services = yield* ClickHouseCloud.service.listServices({ organizationId });
 *   return services.map(({ name, state, region }) => ({ name, state, region }));
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   ClickHouseCloud.CredentialsFromEnv,
 *   ClickHouseCloud.ClickHouseCloudProtocol,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise).then(console.log);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  ClickHouseCloudProtocol,
  ClickHouseCloudPaginatedProtocol,
  type ClickHouseCloudOpError,
  type ClickHouseCloudOpContext,
} from "./protocol.ts";
export { paginateCursor } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
